UPDATE `user` SET status = #{status}, real_name = #{realName}, username = #{username},
    phone = #{phone}, password = #{password}, avatar = NULL, gender = #{gender}, age = #{age},
    emergency_name = #{emergencyName}, emergency_phone = #{emergencyPhone}
, create_time = #{createTime}
, last_login_time = #{lastLoginTime}
WHERE id = #{id}
